style.css:
@-moz-document domain("youtube.com") {
ytd-app ytd-browse[page-subtype="home"],
  ytd-app ytd-watch-flexy {
    background-color: #0e0e11;
    background-image:
      linear-gradient(
        to bottom,
        rgba(12, 12, 15, 0.75),
        rgba(12, 12, 15, 0.86)
      ),
      url("https://i.postimg.cc/0j3VfqsV/needy-girl-overdose.jpg");
    background-size: cover;
    background-position: center;
    background-attachment: fixed;
    background-repeat: no-repeat;
  }

  ytd-app ytd-masthead #background.ytd-masthead,
  ytd-app ytd-browse[page-subtype="home"] ytd-feed-filter-chip-bar-renderer #chips-wrapper {
    background-color: rgba(15, 15, 18, 0.86);
    backdrop-filter: blur(8px);
    border-bottom: 1px solid rgba(255, 255, 255, 0.12);
  }

  ytd-app ytd-mini-guide-renderer,
  ytd-app #guide-wrapper #guide-inner-content {
    background-color: rgba(15, 15, 18, 0.86);
    backdrop-filter: blur(8px);
    border-right: 1px solid rgba(255, 255, 255, 0.12);
  }

  ytd-app ytd-browse[page-subtype="home"] ytd-rich-grid-media,
  ytd-app ytd-browse[page-subtype="home"] ytd-reel-item-renderer {
    background-color: rgba(24, 24, 28, 0.82);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 12px;
    padding: 8px;
    box-sizing: border-box;
  }

  ytd-app ytd-browse[page-subtype="home"] ytd-rich-shelf-renderer #dismissible {
    background-color: rgba(15, 15, 18, 0.78);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 14px;
    padding: 16px;
  }

  ytd-app ytd-watch-flexy #secondary.ytd-watch-flexy,
  ytd-app ytd-watch-flexy ytd-comments#comments {
    background-color: rgba(24, 24, 28, 0.82);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 12px;
    padding: 12px;
    box-sizing: border-box;
  }

  ytd-app ytd-browse[page-subtype="home"] #video-title,
  ytd-app ytd-browse[page-subtype="home"] #metadata-line,
  ytd-app ytd-watch-flexy #content-text {
    text-shadow: 0 1px 2px rgba(0, 0, 0, 0.85);
  }
}
